"""Parcours autonome de grammaire : 6 niveaux, 4 règles validables par niveau."""
from programme import L

GRAMMAIRE = {
'A1': [
 L('Articles et genre', 'En espagnol, les noms ont un genre. L’article défini est el / la / los / las ; l’indéfini est un / una / unos / unas. Attention aux exceptions comme el día et la mano.', 'el libro · la casa · los amigos · una mesa', 'La niña lee un libro en la biblioteca.', 'Quel article défini accompagne « casa » ?', ['el','la','los'], 'la', 'Relève les articles de cinq phrases espagnoles.'),
 L('Singulier et pluriel', 'En général, on ajoute -s après une voyelle et -es après une consonne. Les mots en -z changent z en c : lápiz → lápices.', 'casa → casas · árbol → árboles · luz → luces', 'Las luces iluminan las calles de la ciudad.', 'Quel est le pluriel de « luz » ?', ['luzes','luces','luzs'], 'luces', 'Transforme dix groupes nominaux au pluriel.'),
 L('Accord de l’adjectif', 'Les adjectifs s’accordent en genre et en nombre avec le nom. Bonito → bonita / bonitos / bonitas ; certains restent identiques au masculin et au féminin.', 'un coche rojo · dos casas rojas · una ciudad grande', 'Mi hermana tiene dos gatos negros y una gata blanca.', 'Complète : « Las flores son ___ »', ['bonito','bonitas','bonita'], 'bonitas', 'Décris trois personnes ou objets avec des adjectifs.'),
 L('Pronoms et présent', 'Les pronoms sujets sont yo, tú, él/ella/usted, nosotros, vosotros, ellos/ellas/ustedes. En espagnol on omet souvent le pronom car la terminaison renseigne sur le sujet.', 'yo hablo · tú comes · nosotros vivimos', 'Cada día, Pedro estudia español y sus amigos practican con él.', 'Quelle forme correspond à « nosotros » pour hablar ?', ['hablan','hablamos','hablo'], 'hablamos', 'Présente-toi avec quatre phrases au présent.'),
],
'A2': [
 L('Ser, estar et hay', 'Ser exprime souvent l’identité ou les propriétés ; estar sert notamment à localiser et à exprimer des états ; hay indique l’existence.', 'Soy estudiante. · Estoy cansada. · Hay un parque.', 'En mi barrio hay un mercado. El mercado está cerca de la estación.', 'Complète : « ___ una farmacia aquí »', ['Es','Está','Hay'], 'Hay', 'Compare deux lieux avec ser, estar et hay.'),
 L('Pronoms compléments', 'Les pronoms compléments directs sont me, te, lo/la, nos, os, los/las. Ils précèdent généralement le verbe conjugué. Les pronoms indirects incluent le, les.', '¿Ves el libro? Sí, lo veo. · Le escribo a Ana.', 'Lucía compra las entradas y las guarda en su bolso.', 'Remplace « las entradas » : Lucía ___ guarda.', ['lo','las','les'], 'las', 'Écris quatre phrases avec lo, la, le ou les.'),
 L('Comparatif et superlatif', 'La comparaison d’inégalité utilise más / menos + adjectif + que. L’égalité se formule avec tan… como. Le superlatif relatif ajoute l’article.', 'más alto que · tan rápido como · la más antigua', 'Este tren es más rápido que el autobús, pero menos cómodo.', 'Complète : « más grande ___ »', ['como','que','de'], 'que', 'Compare trois moyens de transport.'),
 L('Passés de base', 'L’imparfait décrit états et habitudes dans le passé ; l’indefinido raconte un événement achevé. Les usages du perfecto composé varient suivant les régions.', 'Antes jugaba. · Ayer jugué. · Hoy he estudiado.', 'Cuando era pequeña, vivía en Sevilla. El año pasado viajé a Granada.', 'Dans « Antes ___ mucho », quelle forme convient ?', ['jugué','jugaba','jugaré'], 'jugaba', 'Raconte une habitude et un événement passé.'),
],
'B1': [
 L('Futur et conditionnel', 'Le futur exprime une action future ou une hypothèse. Le conditionnel introduit souhait, demande polie ou conséquence hypothétique.', 'Mañana viajaré. · Me gustaría conocer México.', 'Si tuviera vacaciones, visitaría más ciudades.', 'Complète : « Me ___ aprender italiano »', ['gustaría','gustó','gusta'], 'gustaría', 'Écris trois projets et deux souhaits.'),
 L('Subjonctif présent', 'On emploie notamment le subjonctif après des verbes de souhait, d’émotion ou de doute lorsque les sujets diffèrent.', 'Quiero que vengas. · Dudo que sea cierto.', 'La profesora espera que todos comprendan el ejercicio.', 'Complète : « Espero que tú ___ »', ['vienes','vengas','vendrás'], 'vengas', 'Exprime trois souhaits et deux doutes.'),
 L('Impératif et interdictions', 'L’impératif affirme ou interdit un comportement. À l’impératif négatif, on utilise le subjonctif présent.', 'Habla más despacio. · No hables tan rápido.', 'El médico le dice a Pablo: «Descansa y no trabajes hoy».', 'Complète l’interdiction : « No ___ »', ['corre','corras','corres'], 'corras', 'Rédige cinq consignes de voyage.'),
 L('Propositions relatives', 'Que, quien, donde, cuyo relient un nom à une proposition qui le précise. Le choix dépend de l’antécédent et de la construction.', 'La chica que canta. · El lugar donde nací.', 'El museo que visitamos ayer está junto al parque.', 'Quel mot relie « El libro ___ leo » ?', ['donde','que','porque'], 'que', 'Décris un livre, une personne et une ville avec des relatives.'),
],
'B2': [
 L('Hypothèse irréelle', 'Avec si + imparfait du subjonctif, la principale se met souvent au conditionnel : on imagine une situation non réalisée ou peu probable.', 'Si tuviera tiempo, viajaría.', 'Si pudiéramos elegir, viviríamos cerca del mar.', 'Complète : « Si ___ más, mejoraría »', ['leo','leyera','leeré'], 'leyera', 'Imagine trois situations alternatives.'),
 L('Regret au passé', 'La construction si + plus-que-parfait du subjonctif peut présenter un passé imaginaire, avec une conséquence au conditionnel passé.', 'Si hubiera sabido, habría llamado.', 'Si hubiéramos salido antes, no habríamos perdido el tren.', 'Complète : « Si lo ___, habría venido »', ['sabía','supiera','hubiera sabido'], 'hubiera sabido', 'Transforme deux événements en regrets.'),
 L('Concession et opposition', 'Aunque + indicatif présente généralement un fait assumé ; + subjonctif permet d’envisager une possibilité ou de ne pas assumer l’information.', 'Aunque llueve, salgo. · Aunque llueva, saldré.', 'Aunque sea complicado, intentaremos resolver el problema.', 'Quel mode contient « aunque sea » ?', ['indicatif','subjonctif','impératif'], 'subjonctif', 'Rédige quatre phrases concessives.'),
 L('Voix passive et impersonnelle', 'La voix passive périphrastique se forme avec ser + participe, accordé avec le sujet. La passive réfléchie emploie se.', 'El puente fue construido. · Se venden libros.', 'La noticia fue publicada ayer y se difundió rápidamente.', 'Quel mot forme la passive avec « construido » ?', ['haber','ser','ir'], 'ser', 'Transforme trois phrases actives en passives.'),
],
'C1': [
 L('Concordance des temps', 'Le temps de la principale et la relation temporelle conditionnent la forme subjonctive : espero que venga / esperaba que viniera.', 'Me alegra que hayas venido. · Dudaba que llegaran.', 'El director esperaba que el equipo hubiera terminado antes del viernes.', 'Complète : « Dudaba que ella ___ »', ['viene','viniera','vendrá'], 'viniera', 'Transforme cinq phrases en récit au passé.'),
 L('Subjonctif et implicite', 'Expressions impersonnelles, appréciations, négation et incertitude guident le mode. Un changement de mode peut modifier le sens de l’énoncé.', 'Busco a alguien que sepa programar. · Conozco a alguien que sabe programar.', 'No creo que los datos permitan sacar esa conclusión.', 'Complète : « No creo que ___ suficiente »', ['es','sea','fue'], 'sea', 'Explique l’effet d’un changement de mode sur trois paires.'),
 L('Périphrases verbales', 'Les périphrases modifient l’aspect ou la modalité : llevar + gérondif, acabar de + infinitif, volver a + infinitif, deber de + infinitif.', 'Llevo dos horas leyendo. · Acabo de llegar.', 'La investigadora lleva meses estudiando este fenómeno.', 'Quelle périphrase signifie « venir de » ?', ['volver a','acabar de','dejar de'], 'acabar de', 'Utilise cinq périphrases dans un récit.'),
 L('Style indirect complexe', 'Au discours indirect, il faut ajuster personnes, repères temporels et temps verbaux sans déformer la parole rapportée.', 'Dijo: «Iré mañana». → Dijo que iría al día siguiente.', 'La portavoz explicó que presentarían el informe la semana siguiente.', 'Quel repère remplace « mañana » au discours indirect passé ?', ['el día siguiente','hoy','ayer'], 'el día siguiente', 'Résume une interview en style indirect.'),
],
'C2': [
 L('Syntaxe et emphase', 'Les détachements, inversions, structures clivées et nominalisations orientent l’information. Une phrase complexe reste claire lorsque les relations syntaxiques sont maîtrisées.', 'Fue ayer cuando lo supimos. · De ahí que se revise el texto.', 'No fue sino después de la votación cuando se conocieron los resultados.', 'Quelle formule met en relief un moment ?', ['Fue ayer cuando…','Tal vez…','Por ejemplo…'], 'Fue ayer cuando…', 'Réécris deux phrases pour en changer le foyer informationnel.'),
 L('Registres et pragmatique', 'L’espagnol varie selon la région, la situation, le degré de politesse et les intentions implicites. Évite une langue artificiellement uniforme.', '¿Podría indicarme…? · Oye, ¿sabes…?', 'El tono de la petición cambia según la confianza entre los interlocutores.', 'Quelle expression convient à une demande très polie ?', ['¡Dime!','¿Podría indicarme…?','¡Oye!'], '¿Podría indicarme…?', 'Écris une demande en trois registres.'),
 L('Constructions historiques', 'Le futur du subjonctif et le passé antérieur survivent surtout dans des textes littéraires anciens ou juridiques ; ils ne sont pas des choix usuels de la conversation actuelle.', 'Quien incumpliere… · Apenas hubo llegado…', 'La disposición se aplicará a quien incumpliere los requisitos previstos.', '« Incumpliere » relève surtout d’un usage…', ['historique / juridique','quotidien moderne','impératif'], 'historique / juridique', 'Modernise deux formulations anciennes.'),
 L('Ambiguïtés et argumentation', 'Analyser les présupposés, portées des négations et ambiguïtés référentielles permet de défendre une interprétation sans la présenter comme unique.', 'No todos vinieron ≠ Nadie vino. · Podría interpretarse que…', 'El editorial no niega los hechos, sino que cuestiona la interpretación dominante.', '« No todos vinieron » signifie…', ['Personne n’est venu','Au moins une personne n’est pas venue','Tout le monde est venu'], 'Au moins une personne n’est pas venue', 'Compare deux interprétations d’une phrase ambiguë.'),
],
}

assert list(GRAMMAIRE)==['A1','A2','B1','B2','C1','C2']
assert all(len(v)==4 for v in GRAMMAIRE.values())
